void gdImageXBM(gdImagePtr image, char* file_name, int fg, gdIOCtx* out) {
    int width = image->sx;
    int height = image->sy;
    int i, j;
    int index = 0;
    char* base_name = file_name;
    unsigned char* pixel_data = (unsigned char*)malloc((width + 7) / 8 * height);
    char buffer[256];
    int bytes_per_line = (width + 7) / 8;

    for (i = 0; i < height; i++) {
        for (j = 0; j < width; j++) {
            int color = gdImageGetPixel(image, j, i);
            if (color == fg) {
                pixel_data[index / 8] |= (0x80 >> (index % 8));
            }
            index++;
        }
    }

    snprintf(buffer, sizeof(buffer), "#define %s_width %d\n", base_name, width);
    gdPutChar(out, buffer[0]);
    for (i = 1; i < strlen(buffer); i++) {
        gdPutChar(out, buffer[i]);
    }

    snprintf(buffer, sizeof(buffer), "#define %s_height %d\n", base_name, height);
    gdPutChar(out, buffer[0]);
    for (i = 1; i < strlen(buffer); i++) {
        gdPutChar(out, buffer[i]);
    }

    snprintf(buffer, sizeof(buffer), "static unsigned char %s_bits[] = {\n", base_name);
    gdPutChar(out, buffer[0]);
    for (i = 1; i < strlen(buffer); i++) {
        gdPutChar(out, buffer[i]);
    }

    for (i = 0; i < height; i++) {
        for (j = 0; j < bytes_per_line; j++) {
            snprintf(buffer, sizeof(buffer), "0x%02x, ", pixel_data[i * bytes_per_line + j]);
            gdPutChar(out, buffer[0]);
            for (int k = 1; k < strlen(buffer); k++) {
                gdPutChar(out, buffer[k]);
            }
        }
        gdPutChar(out, '\n');
    }

    snprintf(buffer, sizeof(buffer), "};\n");
    gdPutChar(out, buffer[0]);
    for (i = 1; i < strlen(buffer); i++) {
        gdPutChar(out, buffer[i]);
    }

    free(pixel_data);
}

