void generateXBM(gdImagePtr image, char* file_name, int fg, gdIOCtx* out) {
    int width = gdImageSX(image);
    int height = gdImageSY(image);
    int i, j;
    char* base_name = file_name;
    char* p = base_name;

    /* Remove path from file name */
    while (*p && p[1]) {
        if (*p == '/') {
            base_name = p + 1;
        }
        p++;
    }

    char width_def[64];
    char height_def[64];
    sprintf(width_def, "#define %s_width %d\n", base_name, width);
    sprintf(height_def, "#define %s_height %d\n", base_name, height);
    gdPutBuf(out, width_def, strlen(width_def));
    gdPutBuf(out, height_def, strlen(height_def));

    char data_def[256];
    sprintf(data_def, "static unsigned char %s_bits[] = {\n    ", base_name);
    gdPutBuf(out, data_def, strlen(data_def));

    for (i = 0; i < height; i++) {
        int row_start = i * width;
        int row_end = row_start + width;
        int row_data = 0;

        for (j = 0; j < width; j++) {
            int pixel = gdImageGetPixel(image, j, i);
            row_data |= ((pixel == fg) << (width - j - 1));
        }

        char row_str[32];
        sprintf(row_str, "0x%02X, ", row_data);
        gdPutBuf(out, row_str, strlen(row_str));

        if ((i + 1) % 8 == 0 || i == height - 1) {
            gdPutBuf(out, "\n    ", 4);
        }
    }

    gdPutBuf(out, "\n};\n", 4);
}

void gdImageXBM(gdImagePtr image, char* file_name, int fg, gdIOCtx* out) {
    int width = image->sx;
    int height = image->sy;
    int i, j, y, byte;
    char* base_name = file_name;
    char* p;
    for (p = file_name; *p; p++) {
        if (*p == '.' && p[1] && p[1] != '/') {
            *p = 0;
            base_name = file_name;
        }
    }

    gdIOCtx_printf(out, "#define %s_width %d\n", base_name, width);
    gdIOCtx_printf(out, "#define %s_height %d\n", base_name, height);

    gdIOCtx_printf(out, "static unsigned char %s_bits[] = {\n  ", base_name);

    for (y = 0; y < height; y++) {
        for (i = 0; i < width; i += 8) {
            byte = 0;
            for (j = 0; j < 8 && i + j < width; j++) {
                int idx = (height - y - 1) * width + (i + j);
                int color = image->pixels[idx % width][idx / width];
                byte |= ((color == fg) << (7 - j));
            }
            gdIOCtx_printf(out, "0x%02X", (unsigned char)byte);
            if (i + 8 < width)
                gdIOCtx_printf(out, ",");
            if (i + 8 < width && (i + 8) % 8 != 0)
                gdIOCtx_printf(out, " ");
            else if (i + 8 < width)
                gdIOCtx_printf(out, ",");
            else
                gdIOCtx_printf(out, " ");
        }
        if (y < height - 1)
            gdIOCtx_printf(out, "\n  ");
        else
            gdIOCtx_printf(out, "\n};\n");
    }
}
